function vt_loadHelpers() {
  const rand = () => Math.random().toString(36).slice(2, 10);
  const generateString = (length) => 'a'.repeat(length);

  const validUser = () => ({
    username: 'user' + rand(),
    email: 'user' + rand() + '@test.com',
    password: pm.collectionVariables.get('passwordConduit')
  });

  const setBody = (user) => {
    pm.collectionVariables.set('vt_signUpBody', JSON.stringify({ user }));
  };

  const assertSignUpError = (field) => {
    pm.test('Assert response status code is 422', () => {
      pm.response.to.have.status(422);
    });
    pm.test('Assert response time is below 2000ms', () => {
      pm.expect(pm.response.responseTime).to.be.below(2000);
    });
    pm.test('Assert response body has errors for ' + field, () => {
      const body = pm.response.json();
      pm.expect(body).to.have.property('errors');
      pm.expect(body.errors).to.have.property(field);
    });
  };

  return { rand, generateString, validUser, setBody, assertSignUpError };
}

function vt_loadProfileHelpers() {
  const rand = () => Math.random().toString(36).slice(2, 10);
  const url = pm.collectionVariables.get('url');

  const send = (options) => new Promise((resolve, reject) => {
    pm.sendRequest(options, (err, res) => (err ? reject(err) : resolve(res)));
  });

  const register = async () => {
    const user = {
      username: 'user' + rand(),
      email: 'user' + rand() + '@test.com',
      password: pm.collectionVariables.get('passwordConduit')
    };
    const res = await send({
      url: url + '/users',
      method: 'POST',
      header: { 'Content-Type': 'application/json' },
      body: { mode: 'raw', raw: JSON.stringify({ user }) }
    });
    return { ...user, token: res.json().user.token };
  };

  const follow = (username, token) => send({
    url: url + '/profiles/' + username + '/follow',
    method: 'POST',
    header: { Authorization: 'Token ' + token }
  });

  const assertProfile = (expectedFollowing) => {
    pm.test('Assert response status code is 200', () => {
      pm.response.to.have.status(200);
    });
    pm.test('Assert response time is below 2000ms', () => {
      pm.expect(pm.response.responseTime).to.be.below(2000);
    });
    pm.test('Assert response body has profile properties', () => {
      const profile = pm.response.json().profile;
      pm.expect(profile).to.have.all.keys('username', 'bio', 'image', 'following');
      pm.expect(profile.username).to.eql(pm.collectionVariables.get('vt_targetUsername'));
    });
    pm.test('Assert following is ' + expectedFollowing, () => {
      pm.expect(pm.response.json().profile.following).to.eql(expectedFollowing);
    });
  };

  return { register, follow, assertProfile };
}
